```tsx
import { useEffect, useId, useRef, useState } from "react";
import "./CodeCard.css";

export interface CodeCardProps {
  title: string;
  code: string;
  onCopy: (code: string) => void;
}

const COPIED_MESSAGE_MS = 2000;

export function CodeCard({ title, code, onCopy }: CodeCardProps) {
  const titleId = useId();
  const [copied, setCopied] = useState(false);
  const timerRef = useRef<number | null>(null);

  useEffect(() => {
    return () => {
      if (timerRef.current !== null) window.clearTimeout(timerRef.current);
    };
  }, []);

  function handleCopy() {
    onCopy(code);
    setCopied(true);
    if (timerRef.current !== null) window.clearTimeout(timerRef.current);
    timerRef.current = window.setTimeout(() => setCopied(false), COPIED_MESSAGE_MS);
  }

  return (
    <section className="code-card" aria-labelledby={titleId}>
      <header className="code-card__header">
        <h3 id={titleId} className="code-card__title">{title}</h3>
        <button type="button" className="code-card__copy" onClick={handleCopy}>
          Copy
        </button>
      </header>
      <div className="code-card__scroll" role="region" tabIndex={0} aria-labelledby={titleId}>
        <pre className="code-card__block">
          <code>{code}</code>
        </pre>
      </div>
      <p className="code-card__status" role="status">
        {copied ? "Copied to clipboard" : ""}
      </p>
    </section>
  );
}
