  font-size: clamp(0.8125rem, 1.3vw, 0.95rem);
  line-height: 1.6;
  color: var(--ink);
  white-space: pre;
}

.code-card__status {
  margin: 0;
  min-height: 1.25em;
  font-size: clamp(0.8125rem, 1.2vw, 0.9375rem);
  color: var(--myelin);
  font-variant-numeric: tabular-nums;
}

.code-card__copy {
  transition: background-color 150ms ease;
}

:root[data-motion="reduce"] .code-card__copy,
:root[data-motion="reduce"] .code-card__copy:hover {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .code-card__copy {
    transition: none;
  }
}
